reference_solution:
def numIslands(grid):
    if not grid:
        return 0
    R, C = len(grid), len(grid[0])
    seen = [[False] * C for _ in range(R)]
    n = 0
    for i in range(R):
        for j in range(C):
            if grid[i][j] == 1 and not seen[i][j]:
                n += 1
                st = [(i, j)]
                seen[i][j] = True
                while st:
                    r, c = st.pop()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == 1 and not seen[nr][nc]:
                            seen[nr][nc] = True
                            st.append((nr, nc))
    return n

brute_force_solution:
def numIslands(grid):
    if not grid:
        return 0
    R, C = len(grid), len(grid[0])
    p = list(range(R * C))
    def f(x):
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x
    for i in range(R):
        for j in range(C):
            if grid[i][j] == 1:
                for di, dj in ((1, 0), (0, 1)):
                    ni, nj = i + di, j + dj
                    if ni < R and nj < C and grid[ni][nj] == 1:
                        p[f(i * C + j)] = f(ni * C + nj)
    return len({f(i * C + j) for i in range(R) for j in range(C) if grid[i][j] == 1})

